// Status codes. dimsvc methods return a Win32 error code (32-bit) as their return
// value ([MS-RRASM] 3.1.4; [MS-ERREF] 2.2). The values below are the ones commonly
// returned across the interface's methods; any other code is rendered as hex by
// StatusString. ERROR_NO_MORE_ITEMS terminates the RMIBEntryGetNext enumeration and
// is a success-like sentinel, mirroring STATUS_MORE_ENTRIES tolerance elsewhere.
const (
	StatusSuccess             uint32 = 0x00000000 // ERROR_SUCCESS
	StatusInvalidFunction     uint32 = 0x00000001 // ERROR_INVALID_FUNCTION
	StatusFileNotFound        uint32 = 0x00000002 // ERROR_FILE_NOT_FOUND
	StatusAccessDenied        uint32 = 0x00000005 // ERROR_ACCESS_DENIED
	StatusInvalidHandle       uint32 = 0x00000006 // ERROR_INVALID_HANDLE
	StatusNotEnoughMemory     uint32 = 0x00000008 // ERROR_NOT_ENOUGH_MEMORY
	StatusNotSupported        uint32 = 0x00000032 // ERROR_NOT_SUPPORTED
	StatusInvalidParameter    uint32 = 0x00000057 // ERROR_INVALID_PARAMETER
	StatusInsufficientBuffer  uint32 = 0x0000007A // ERROR_INSUFFICIENT_BUFFER
	StatusAlreadyExists       uint32 = 0x000000B7 // ERROR_ALREADY_EXISTS
	StatusNoMoreItems         uint32 = 0x00000103 // ERROR_NO_MORE_ITEMS
	StatusServiceDoesNotExist uint32 = 0x00000424 // ERROR_SERVICE_DOES_NOT_EXIST
)

